# --------------------------------------------------------------------------- errors


class IndiaDataError(RuntimeError):
    """Base class for India data failures callers can report and continue past."""


class McpTransportError(IndiaDataError):
    """The MCP server could not be reached or replied with an unusable body."""


class McpToolError(IndiaDataError):
    """The MCP tool ran but reported an error."""


class SymbolNotFoundError(McpToolError):
    """NSE has no data for the symbol (or for the requested window)."""


class CalendarDependencyMissingError(IndiaDataError):
    """pandas-market-calendars is not installed (CLI exit status 2)."""


# --------------------------------------------------------------------------- helpers


def _utcnow() -> datetime:
    return datetime.now(timezone.utc)


def _number(value: Any, *, allow_zero: bool = False) -> float | None:
    """Return a finite real number (> 0, or >= 0 when allowed), else None."""
    if isinstance(value, bool) or not isinstance(value, numbers.Real):
        return None
    try:
        if not math.isfinite(value):
            return None
    except (TypeError, ValueError, OverflowError):
        return None
    if value > 0 or (allow_zero and value == 0):
        return value
    return None


def _parse_date(value: Any) -> date | None:
    if isinstance(value, date) and not isinstance(value, datetime):
        return value
    if not isinstance(value, str):
        return None
    try:
        return date.fromisoformat(value.strip()[:10])
    except ValueError:
        return None


def _months_back(day: date, months: int) -> date:
    """``day`` minus whole calendar months, clamping to the month's last day."""
    month_index = day.year * 12 + (day.month - 1) - months
    year, month = divmod(month_index, 12)
    month += 1
    last = _calendar.monthrange(year, month)[1]
    return date(year, month, min(day.day, last))


def _require_aware(value: datetime, name: str = "now") -> datetime:
    if not isinstance(value, datetime) or value.tzinfo is None or value.utcoffset() is None:
        raise ValueError(f"{name} must be a timezone-aware datetime")
    return value


def safe_symbol(symbol: str) -> str:
    """Normalise an NSE symbol and reject anything unsafe as a file name."""
    if not isinstance(symbol, str):
        raise ValueError("symbol must be a string")
    normalized = symbol.strip().upper()
    if not re.fullmatch(r"[A-Z0-9][A-Z0-9&\-_.]{0,31}", normalized) or ".." in normalized:
        raise ValueError(f"Invalid NSE symbol: {symbol!r}")
    return normalized


def _slug(name: str) -> str:
    slug = re.sub(r"[^A-Z0-9]+", "_", name.strip().upper()).strip("_")
    if not slug:
        raise ValueError(f"Invalid index name: {name!r}")
    return slug


def _read_json(path: Path) -> Any | None:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return None
    except (OSError, ValueError) as exc:
        raise IndiaDataError(f"Corrupt cache file {path}: {exc}") from exc


def _write_json_atomic(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(data, handle, ensure_ascii=False, separators=(",", ":"))
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


# --------------------------------------------------------------------------- MCP client


def parse_mcp_body(body: str, content_type: str, request_id: Any = None) -> dict:
    """Decode one JSON-RPC message from a JSON or Server-Sent Events body."""
    if "event-stream" in (content_type or "").lower():
        messages = []
        for block in re.split(r"\r?\n\r?\n", body):
            data_lines = [
                line[5:].lstrip(" ") for line in block.splitlines() if line.startswith("data:")
            ]
            if not data_lines:
                continue
            try:
                messages.append(json.loads("\n".join(data_lines)))
            except ValueError as exc:
                raise McpTransportError(f"Malformed SSE data from MCP server: {exc}") from exc
        for message in messages:
            if not isinstance(message, dict):
                continue
            if request_id is not None and message.get("id") == request_id:
                return message
            if request_id is None and ("result" in message or "error" in message):
                return message
        raise McpTransportError("MCP server stream carried no reply for the request")
    try:
        message = json.loads(body)
    except ValueError as exc:
        raise McpTransportError(f"MCP server returned non-JSON body: {exc}") from exc
    if not isinstance(message, dict):
        raise McpTransportError("MCP server returned a non-object JSON body")
    return message


def tool_result_payload(message: dict) -> Any:
    """Extract a tool's payload, raising for JSON-RPC errors and error payloads."""
    if "error" in message:
        error = message["error"]
        detail = error.get("message") if isinstance(error, dict) else error
        raise McpToolError(f"MCP error: {detail}")
    result = message.get("result")
    if not isinstance(result, dict):
        raise McpTransportError("MCP reply has no result object")
    content = result.get("content") or []
    text = ""
    for item in content:
        if isinstance(item, dict) and item.get("type") == "text":
            text = item.get("text") or ""
            break
    if result.get("isError"):
        raise McpToolError(f"MCP tool error: {text or 'unknown error'}")
    try:
        payload = json.loads(text)
    except ValueError:
        return text
    if isinstance(payload, dict) and isinstance(payload.get("error"), str):
        error_text = payload["error"]
        if "not found" in error_text.lower():
            raise SymbolNotFoundError(error_text)
        raise McpToolError(error_text)
    return payload


class McpHttpClient:
    """Minimal streamable-HTTP MCP client (tools/call only)."""

    def __init__(
        self,
        url: str = NSE_BHAVCOPY_URL,
        *,
        opener: Callable[..., Any] | None = None,
        timeout: float = DEFAULT_TIMEOUT,
        max_retries: int = 3,
        backoff_seconds: float = 1.0,
        min_interval_seconds: float = 0.15,
        sleep: Callable[[float], None] = time.sleep,
        clock: Callable[[], float] = time.monotonic,
        user_agent: str = MCP_USER_AGENT,
    ):
        if timeout is None or timeout <= 0:
            raise ValueError("timeout must be positive")
        self.url = url
        self._opener = opener or urllib.request.urlopen
        self._timeout = float(timeout)
        self._max_retries = max(0, int(max_retries))
        self._backoff = float(backoff_seconds)
        self._min_interval = float(min_interval_seconds)
        self._sleep = sleep
        self._clock = clock
        self._user_agent = user_agent
        self._session_id: str | None = None
        self._initialized = False
        self._next_id = 1
        self._last_request: float | None = None

    # -- transport

    def _throttle(self) -> None:
        if self._min_interval <= 0 or self._last_request is None:
            return
        wait = self._min_interval - (self._clock() - self._last_request)
        if wait > 0:
            self._sleep(wait)

    def _send_once(self, body: dict) -> tuple:
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "User-Agent": self._user_agent,
        }
        if self._session_id:
            headers["Mcp-Session-Id"] = self._session_id
        request = urllib.request.Request(
            self.url, data=json.dumps(body).encode("utf-8"), headers=headers, method="POST"
        )
        self._throttle()
        try:
            with self._opener(request, timeout=self._timeout) as response:
                raw = response.read()
                response_headers = response.headers
        finally:
            self._last_request = self._clock()
        session_id = response_headers.get("Mcp-Session-Id") if response_headers else None
        content_type = (response_headers.get("Content-Type") if response_headers else "") or ""
        text = raw.decode("utf-8", errors="replace") if isinstance(raw, bytes) else str(raw)
        return session_id, content_type, text

    def _send(self, body: dict) -> tuple:
        attempt = 0
        while True:
            try:
                return self._send_once(body)
            except urllib.error.HTTPError as exc:
                if exc.code not in RETRYABLE_HTTP or attempt >= self._max_retries:
                    raise McpTransportError(f"HTTP {exc.code} from {self.url}") from exc
            except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as exc:
                if attempt >= self._max_retries:
                    raise McpTransportError(f"Cannot reach {self.url}: {exc}") from exc
            self._sleep(self._backoff * (2**attempt))
            attempt += 1

    def _request_id(self) -> int:
        value = self._next_id
        self._next_id += 1
        return value

    def _initialize(self) -> None:
        request_id = self._request_id()
        body = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": "initialize",
            "params": {
                "protocolVersion": MCP_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {"name": "india-data", "version": "0.1"},
            },
        }
        session_id, content_type, text = self._send(body)
        message = parse_mcp_body(text, content_type, request_id=request_id)
        if "error" in message:
            raise McpTransportError(f"MCP initialize failed: {message['error']}")
        if session_id:
            self._session_id = session_id
        try:  # Some servers do not need this notification; never fail on it.
            self._send_once({"jsonrpc": "2.0", "method": "notifications/initialized"})
        except (urllib.error.URLError, OSError):
            pass
        self._initialized = True

    def call_tool(self, name: str, arguments: dict) -> Any:
        if not self._initialized:
            self._initialize()
        request_id = self._request_id()
        body = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": "tools/call",
            "params": {"name": name, "arguments": arguments},
        }
        _, content_type, text = self._send(body)
        return tool_result_payload(parse_mcp_body(text, content_type, request_id=request_id))


# --------------------------------------------------------------------------- history


def normalize_stock_bar(raw: Any) -> dict | None:
    """Map an NSE bhavcopy row to the common bar shape; invalid rows -> None."""
    if not isinstance(raw, dict):
        return None
    day = _parse_date(raw.get("date"))
    prices = {
        "open": _number(raw.get("open")),
        "high": _number(raw.get("high")),
        "low": _number(raw.get("low")),
        "close": _number(raw.get("close")),
    }
    if day is None or any(v is None for v in prices.values()):
        return None
    if prices["high"] < prices["low"]:
        return None
    volume = _number(raw.get("volume"), allow_zero=True)
    return {
        "date": day.isoformat(),
        **prices,
        "prev_close": _number(raw.get("prevClose")),
        "volume": int(volume) if volume is not None else None,
        "value": _number(raw.get("totalTradedValue"), allow_zero=True),
        "series": str(raw.get("series") or "").upper() or None,
    }


def normalize_index_bar(raw: Any) -> dict | None:
    if not isinstance(raw, dict):
        return None
    day = _parse_date(raw.get("date"))
    prices = {k: _number(raw.get(k)) for k in ("open", "high", "low", "close")}
    if day is None or any(v is None for v in prices.values()):
        return None
    volume = _number(raw.get("volume"), allow_zero=True)
    return {
        "date": day.isoformat(),
        **prices,
        "volume": int(volume) if volume is not None else None,
        "turnover_cr": _number(raw.get("turnoverCr"), allow_zero=True),
        "pe": _number(raw.get("pe")),
        "pb": _number(raw.get("pb")),
        "div_yield": _number(raw.get("divYield"), allow_zero=True),
    }


def _prefer(existing: dict | None, candidate: dict) -> dict:
    if existing is None:
        return candidate
    rank_old = SERIES_RANK.get(existing.get("series") or "", 9)
    rank_new = SERIES_RANK.get(candidate.get("series") or "", 9)
    return candidate if rank_new < rank_old else existing


def _fetch_chunked(
    client: McpHttpClient,
    tool: str,
    base_args: dict,
    start: date,
    end: date,
    normalizer: Callable[[Any], dict | None],
    label: str,
) -> list:
    if start > end:
        raise ValueError(f"start {start} is after end {end}")
    by_date: dict = {}
    found_any = False
    cursor = end
    for _ in range(MAX_CHUNKS):
        if cursor < start:
            break
        months = 1 if (cursor - start).days < 28 else HISTORY_CHUNK_MONTHS
        window_start = _months_back(cursor, months)
        args = dict(base_args, months=months, endDate=cursor.isoformat())
        try:
            payload = client.call_tool(tool, args)
        except SymbolNotFoundError:
            payload = None  # a hole in NSE's archive, keep walking back
        next_cursor = None
        if isinstance(payload, dict):
            found_any = True
            for raw in payload.get("data") or []:
                bar = normalizer(raw)
                if bar is None:
                    continue
                day = date.fromisoformat(bar["date"])
                if start <= day <= end:
                    by_date[bar["date"]] = _prefer(by_date.get(bar["date"]), bar)
            next_cursor = _parse_date(payload.get("next_end_date"))
        if next_cursor is None or next_cursor >= cursor:
            next_cursor = window_start - timedelta(days=1)
        cursor = next_cursor
    else:
        raise IndiaDataError(f"Too many history chunks for {label}")
    if not found_any:
        raise SymbolNotFoundError(f"No NSE price history for {label} between {start} and {end}")
    return [by_date[key] for key in sorted(by_date)]


def fetch_stock_history(client: McpHttpClient, symbol: str, start: date, end: date) -> list:
    """Raw (unadjusted) daily bars for ``symbol`` in [start, end], oldest first."""
    sym = safe_symbol(symbol)
    return _fetch_chunked(
        client, "get_stock_history", {"symbol": sym}, start, end, normalize_stock_bar, sym
    )


def fetch_index_history(client: McpHttpClient, index_name: str, start: date, end: date) -> list:
    """Daily index bars (with real volume, turnover, PE/PB) in [start, end]."""
    name = index_name.strip()
    if not name:
        raise ValueError("index name is required")
    return _fetch_chunked(
        client, "get_index_history", {"indexName": name}, start, end, normalize_index_bar, name
    )


def fetch_corporate_actions(client: McpHttpClient, symbol: str, start: date, end: date) -> list:
    sym = safe_symbol(symbol)
    payload = client.call_tool(
        "get_corporate_actions",
        {"symbol": sym, "fromDate": start.isoformat(), "toDate": end.isoformat()},
    )
    rows = payload.get("actions") if isinstance(payload, dict) else None
    actions = []
    for raw in rows or []:
        if not isinstance(raw, dict):
            continue
        ex_date = _parse_date(raw.get("exDate"))
        if ex_date is None:
            continue
        factor = raw.get("adjustmentFactor")
        actions.append(
            {
                "ex_date": ex_date.isoformat(),
                "action_type": str(raw.get("actionType") or "OTHER").upper(),
                "purpose": str(raw.get("purpose") or ""),
                "factor": float(factor) if _number(factor) is not None else None,
            }
        )
    actions.sort(key=lambda a: a["ex_date"])
    return actions


# --------------------------------------------------------------------------- adjustment


def adjustment_factors(actions: list) -> list:
    """``[(ex_date, factor)]`` for price-changing actions; same-day factors multiply."""
    combined: dict = {}
    for action in actions or []:
        factor = _number(action.get("factor")) if isinstance(action, dict) else None
        ex_date = _parse_date(action.get("ex_date")) if isinstance(action, dict) else None
        if factor is None or ex_date is None or factor == 1.0:
            continue
        key = ex_date.isoformat()
        combined[key] = combined.get(key, 1.0) * factor
    return [(day, f) for day, f in sorted(combined.items()) if not math.isclose(f, 1.0)]


def adjust_bars(bars: list, actions: list) -> list:
    """Back-adjust bars before each ex-date: price x factor, volume / factor."""
    events = adjustment_factors(actions)
    out = []
    for bar in bars:
        factor = 1.0
        for ex_date, f in events:
            if bar["date"] < ex_date:
                factor *= f
        new = dict(bar)
        if factor != 1.0:
            for field in PRICE_FIELDS:
                if new.get(field) is not None:
                    new[field] = round(new[field] * factor, 4)
            if new.get("volume") is not None:
                new["volume"] = int(round(new["volume"] / factor))
        new["adj_factor"] = factor
        out.append(new)
    return out


def find_unexplained_jumps(bars: list, actions: list, threshold: float = 0.20) -> list:
    """Close-to-close moves beyond ``threshold`` that no adjustment factor explains."""
    applied = {day for day, _ in adjustment_factors(actions)}
    neutral: dict = {}
    for action in actions or []:
        if isinstance(action, dict) and action.get("action_type") != "DIVIDEND":
            if action.get("ex_date") not in applied:
                neutral.setdefault(action.get("ex_date"), []).append(action.get("action_type"))
    warnings = []
    for previous, current in zip(bars, bars[1:]):
        prev_close, close = previous.get("close"), current.get("close")
        if not prev_close or not close or current["date"] in applied:
            continue
        change = close / prev_close - 1.0
        if abs(change) <= threshold:
            continue
        if current["date"] in neutral:
            types = "/".join(sorted(set(neutral[current["date"]])))
            note = (
                f"{types} corporate action on this ex-date has a neutral factor "
                "(possible demerger); history before it is not adjusted"
            )
        else:
            note = "no corporate action explains this move"
        warnings.append(
            {"date": current["date"], "change_pct": round(change * 100, 2), "note": note}
        )
    return warnings


# --------------------------------------------------------------------------- calendar


def nse_sessions(start: date, end: date) -> list:
    """NSE equity trading days in [start, end] (XBOM schedule + Muhurat sessions)."""
    try:
        import pandas_market_calendars as mcal
    except ImportError as exc:
        raise CalendarDependencyMissingError(REQUIREMENTS_HINT) from exc
    schedule = mcal.get_calendar(CALENDAR_CODE).schedule(
        start_date=start.isoformat(), end_date=end.isoformat()
    )
    days = {stamp.date() for stamp in schedule.index}
    days.update(d for d in MUHURAT_SESSIONS if start <= d <= end)
    return sorted(days)


def latest_completed_session(
    now: datetime,
    *,
    sessions_fn: Callable[[date, date], list] = nse_sessions,
    cutoff: dtime = EOD_CUTOFF,
) -> date:
    """Most recent session whose bhavcopy is final as of ``now`` (IST cutoff)."""
    local = _require_aware(now).astimezone(IST)
    today = local.date()
    sessions = sessions_fn(today - timedelta(days=21), today)
    if today in sessions and local.time() >= cutoff:
        return today
    earlier = [d for d in sessions if d < today]
    if not earlier:
        raise IndiaDataError(f"No NSE session found in the 3 weeks before {today}")
    return earlier[-1]


def drop_muhurat_sessions(bars: list) -> tuple:
    """Remove Diwali Muhurat sessions (one-hour, very low volume) from bars.

    Volume-relative signals (distribution days, follow-through days, volume
    ratios) would otherwise treat the next ordinary session as "higher volume".
    Returns (kept_bars, removed_dates).
    """
    muhurat = {d.isoformat() for d in MUHURAT_SESSIONS}
    kept = [b for b in bars if b.get("date") not in muhurat]
    removed = sorted(b["date"] for b in bars if b.get("date") in muhurat)
    return kept, removed


def normalize_results_events(payload: Any) -> list:
    """Results board-meeting dates from DalalOS or Drishti JSON, deduplicated.

    Accepts a DalalOS ``get_market_calendar`` / ``get_upcoming_results`` reply
    (``{"data": {"events" | "results": [...]}}``, ``nse_symbol`` + ``date`` or
    ``meeting_date``) or a Drishti ``get_upcoming_earnings`` reply
    (``{"data": [{"symbol", "date", "quarter", ...}]}``), or a list of either,
    or several such replies in a list. Rows without an NSE symbol (BSE-only
    scrips) are skipped. Returns ``[{symbol, date, quarter, company, source}]``
    sorted by date then symbol.
    """
    rows: list = []

    def collect(obj: Any) -> None:
        if isinstance(obj, list):
            for item in obj:
                collect(item)
            return
        if not isinstance(obj, dict):
            return
        for key in ("data", "events", "results"):
            if isinstance(obj.get(key), (list, dict)):
                collect(obj[key])
                return
        rows.append(obj)

    collect(payload)
    seen: dict = {}
    for row in rows:
        if row.get("type") not in (None, "results"):
            continue
        raw_symbol = row.get("nse_symbol") or row.get("symbol")
        day = _parse_date(row.get("meeting_date") or row.get("date"))
        if not raw_symbol or day is None:
            continue
        try:
            symbol = safe_symbol(str(raw_symbol))
        except ValueError:
            continue
        source = "drishti" if "event_id" in row or "bm_desc" in row else "dalalos"
        key = (symbol, day.isoformat())
        seen.setdefault(
            key,
            {
                "symbol": symbol,
                "date": day.isoformat(),
                "quarter": row.get("quarter"),
                "company": row.get("company") or row.get("name") or "",
                "source": source,
            },
        )
    return [seen[k] for k in sorted(seen, key=lambda k: (k[1], k[0]))]


# --------------------------------------------------------------------------- cache


def default_cache_dir() -> Path:
    override = os.environ.get(CACHE_ENV)
    return Path(override) if override else Path.cwd() / ".cache" / "india-data"


def _merge_bars(old: list, new: list) -> list:
    by_date = {bar["date"]: bar for bar in old}
    by_date.update({bar["date"]: bar for bar in new})
    return [by_date[key] for key in sorted(by_date)]


class BarCache:
    """Disk cache of raw NSE bars + corporate actions; adjusts on read."""

    def __init__(
        self,
        root: Path,
        client: McpHttpClient | None = None,
        *,
        sessions_fn: Callable[[date, date], list] = nse_sessions,
        now_fn: Callable[[], datetime] = _utcnow,
    ):
        self.root = Path(root)
        self._client = client
        self._sessions_fn = sessions_fn
        self._now_fn = now_fn

    @property
    def client(self) -> McpHttpClient:
        if self._client is None:
            self._client = McpHttpClient()
        return self._client

    def _target_end(self, end: date) -> date:
        latest = latest_completed_session(self._now_fn(), sessions_fn=self._sessions_fn)
        return min(end, latest)

    def _sync(self, path: Path, start: date, target_end: date, fetch: Callable) -> tuple:
        """Make the cache entry cover [start, target_end]; return (entry, fetched)."""
        entry = _read_json(path)
        if entry is None:
            bars = fetch(start, target_end)
            entry = {
                "bars": bars,
                "coverage_start": start.isoformat(),
                "coverage_end": target_end.isoformat(),
            }
            return entry, True
        fetched = False
        cov_start = date.fromisoformat(entry["coverage_start"])
        cov_end = date.fromisoformat(entry["coverage_end"])
        if start < cov_start:
            entry["bars"] = _merge_bars(
                self._fetch_partial(fetch, start, cov_start - timedelta(days=1)), entry["bars"]
            )
            entry["coverage_start"] = start.isoformat()
            fetched = True
        if target_end > cov_end:
            entry["bars"] = _merge_bars(
                entry["bars"], self._fetch_partial(fetch, cov_end, target_end)
            )
            entry["coverage_end"] = target_end.isoformat()
            fetched = True
        return entry, fetched

    @staticmethod
    def _fetch_partial(fetch: Callable, start: date, end: date) -> list:
        try:
            return fetch(start, end)
        except SymbolNotFoundError:
            return []  # gap or suspension inside an otherwise known symbol

    def _envelope(self, kind: str, key: str, start: date, end: date, entry: dict) -> dict:
        bars = [b for b in entry["bars"] if start.isoformat() <= b["date"] <= end.isoformat()]
        return {
            kind: key,
            "exchange": EXCHANGE,
            "currency": CURRENCY,
            "timezone": TIMEZONE_NAME,
            "start": start.isoformat(),
            "end": end.isoformat(),
            "as_of": entry["coverage_end"],
            "bars": bars,
        }

    def stock_bars(self, symbol: str, start: date, end: date, *, adjusted: bool = True) -> dict:
        sym = safe_symbol(symbol)
        target_end = self._target_end(end)
        if target_end < start:
            raise ValueError(f"No completed NSE session between {start} and {end}")
        path = self.root / "stocks" / f"{sym}.json"
        entry, fetched = self._sync(
            path, start, target_end, lambda s, e: fetch_stock_history(self.client, sym, s, e)
        )
        if fetched or "actions" not in entry:
            entry["actions"] = fetch_corporate_actions(
                self.client,
                sym,
                date.fromisoformat(entry["coverage_start"]),
                date.fromisoformat(entry["coverage_end"]),
            )
            entry["symbol"] = sym
            entry["fetched_at"] = _require_aware(self._now_fn()).isoformat()
            _write_json_atomic(path, entry)
        actions = [a for a in entry["actions"] if a["ex_date"] <= entry["coverage_end"]]
        result = self._envelope("symbol", sym, start, end, entry)
        adjusted_bars = adjust_bars(result["bars"], actions)
        result["warnings"] = find_unexplained_jumps(adjusted_bars, actions)
        if adjusted:
            result["bars"] = adjusted_bars
        else:
            result["bars"] = [dict(b, adj_factor=1.0) for b in result["bars"]]
        result["adjusted"] = adjusted
        result["actions"] = actions
        return result

    def index_bars(self, index_name: str, start: date, end: date) -> dict:
        slug = _slug(index_name)
        target_end = self._target_end(end)
        if target_end < start:
            raise ValueError(f"No completed NSE session between {start} and {end}")
        path = self.root / "indices" / f"{slug}.json"
        entry, fetched = self._sync(
            path,
            start,
            target_end,
            lambda s, e: fetch_index_history(self.client, index_name, s, e),
        )
        if fetched:
            entry["index"] = index_name.strip()
            entry["fetched_at"] = _require_aware(self._now_fn()).isoformat()
            _write_json_atomic(path, entry)
        return self._envelope("index", index_name.strip(), start, end, entry)


# --------------------------------------------------------------------------- universe


def parse_constituents_csv(text: str) -> list:
    reader = csv.DictReader(io.StringIO(text.lstrip("﻿")))
    rows = []
    for raw in reader:
        clean = {(k or "").strip(): (v or "").strip() for k, v in raw.items()}
        symbol = clean.get("Symbol")
        if not symbol:
            continue
        rows.append(
            {
                "symbol": symbol.upper(),
                "company": clean.get("Company Name", ""),
                "industry": clean.get("Industry", ""),
                "series": clean.get("Series", ""),
                "isin": clean.get("ISIN Code", ""),
            }
        )
    return rows


def load_universe(
    key: str,
    cache_root: Path,
    *,
    opener: Callable[..., Any] | None = None,
    now_fn: Callable[[], datetime] = _utcnow,
    max_age_days: int = 7,
    timeout: float = DEFAULT_TIMEOUT,
) -> list:
    """Constituents of a Nifty index from NSE's public CSV (cached for a week)."""
    normalized = (key or "").strip().lower().replace(" ", "").replace("_", "")
    if normalized not in UNIVERSE_FILES:
        raise ValueError(f"Unknown universe {key!r}; expected one of {', '.join(UNIVERSE_FILES)}")
    directory = Path(cache_root) / "universe"
    csv_path = directory / f"{normalized}.csv"
    meta_path = directory / f"{normalized}.meta.json"
    now = _require_aware(now_fn())
    meta = _read_json(meta_path) or {}
    fetched_at = meta.get("fetched_at")
    if csv_path.exists() and fetched_at:
        age = now - datetime.fromisoformat(fetched_at)
        if age < timedelta(days=max_age_days):
            return parse_constituents_csv(csv_path.read_text(encoding="utf-8"))
    url = NSE_INDEX_CSV_BASE + UNIVERSE_FILES[normalized]
    request = urllib.request.Request(
        url, headers={"User-Agent": BROWSER_USER_AGENT, "Accept": "text/csv,*/*"}
    )
    try:
        with (opener or urllib.request.urlopen)(request, timeout=timeout) as response:
            text = response.read().decode("utf-8-sig", errors="replace")
        rows = parse_constituents_csv(text)
        if not rows:
            raise IndiaDataError(f"{url} returned no constituents")
    except (urllib.error.URLError, OSError, IndiaDataError) as exc:
        if csv_path.exists():
            print(f"Warning: using stale {normalized} list ({exc})", file=sys.stderr)
            return parse_constituents_csv(csv_path.read_text(encoding="utf-8"))
        raise IndiaDataError(f"Cannot download {url}: {exc}") from exc
    directory.mkdir(parents=True, exist_ok=True)
    csv_path.write_text(text, encoding="utf-8")
    _write_json_atomic(meta_path, {"url": url, "fetched_at": now.isoformat()})
    return rows


# --------------------------------------------------------------------------- metered sources


def _check_source(source: str) -> str:
    if source not in CREDIT_BUDGETS:
        raise ValueError(f"Unknown metered source {source!r}; expected {', '.join(CREDIT_BUDGETS)}")
    return source


class CreditLedger:
    """Append-only JSONL log of credits spent on DalalOS / Drishti calls."""

    def __init__(self, path: Path):
        self.path = Path(path)

    def record(
        self,
        source: str,
        tool: str,
        credits: float,
        *,
        when: datetime | None = None,
        note: str = "",
    ) -> dict:
        _check_source(source)
        if not isinstance(tool, str) or not tool.strip():
            raise ValueError("tool is required")
        if _number(credits, allow_zero=True) is None:
            raise ValueError("credits must be a non-negative number")
        when = _require_aware(when, "when") if when is not None else _utcnow()
        entry = {
            "ts": when.isoformat(),
            "source": source,
            "tool": tool.strip(),
            "credits": credits,
            "note": note,
        }
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(entry) + "\n")
        return entry

    def entries(self) -> list:
        if not self.path.exists():
            return []
        out = []
        for line in self.path.read_text(encoding="utf-8").splitlines():
            try:
                entry = json.loads(line)
                entry["_ts"] = datetime.fromisoformat(entry["ts"]).astimezone(IST)
            except (ValueError, KeyError, TypeError):
                continue
            out.append(entry)
        return out

    def status(self, now: datetime | None = None) -> dict:
        now = _require_aware(now or _utcnow()).astimezone(IST)
        period = now.strftime("%Y-%m")
        entries = self.entries()
        report: dict = {"warnings": []}
        for source, budget in CREDIT_BUDGETS.items():
            mine = [e for e in entries if e.get("source") == source]
            if budget["kind"] == "monthly":
                mine = [e for e in mine if e["_ts"].strftime("%Y-%m") == period]
            used = sum(
                e["credits"] for e in mine if _number(e.get("credits"), allow_zero=True) is not None
            )
            remaining = budget["credits"] - used
            report[source] = {
                "kind": budget["kind"],
                "period": period if budget["kind"] == "monthly" else "lifetime",
                "budget": budget["credits"],
                "used": used,
                "remaining": remaining,
                "calls": len(mine),
            }
            if budget["kind"] == "monthly" and used >= budget["warn_fraction"] * budget["credits"]:
                report["warnings"].append(
                    f"{source}: {used}/{budget['credits']} credits used in {period} "
                    f"(>= {int(budget['warn_fraction'] * 100)}%); shortlist-only until the reset"
                )
            if budget["kind"] == "lifetime" and remaining < budget["warn_remaining"]:
                report["warnings"].append(
                    f"{source}: only {remaining} of {budget['credits']} lifetime credits left"
                )
        return report


class MeteredCache:
    """TTL cache for DalalOS / Drishti responses saved from Claude sessions."""

    def __init__(self, root: Path):
        self.root = Path(root) / "metered"

    def _path(self, source: str, tool: str, args: dict) -> Path:
        _check_source(source)
        if not re.fullmatch(r"[a-z0-9_]{1,64}", tool or ""):
            raise ValueError(f"Invalid tool name {tool!r}")
        key = hashlib.sha256(json.dumps(args, sort_keys=True, default=str).encode()).hexdigest()
        return self.root / source / tool / f"{key[:24]}.json"

    def put(
        self,
        source: str,
        tool: str,
        args: dict,
        payload: Any,
        *,
        ttl_days: float,
        now: datetime | None = None,
    ) -> Path:
        if _number(ttl_days) is None:
            raise ValueError("ttl_days must be positive")
        now = _require_aware(now or _utcnow())
        path = self._path(source, tool, args)
        _write_json_atomic(
            path,
            {
                "source": source,
                "tool": tool,
                "args": args,
                "stored_at": now.isoformat(),
                "expires_at": (now + timedelta(days=ttl_days)).isoformat(),
                "payload": payload,
            },
        )
        return path

    def get(self, source: str, tool: str, args: dict, *, now: datetime | None = None) -> Any:
        now = _require_aware(now or _utcnow())
        entry = _read_json(self._path(source, tool, args))
        if not entry or datetime.fromisoformat(entry["expires_at"]) <= now:
            return None
        return entry["payload"]


# --------------------------------------------------------------------------- CLI


def _iso_date(value: str) -> date:
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"expected YYYY-MM-DD, got {value!r}") from exc


def _json_object(value: str) -> dict:
    try:
        parsed = json.loads(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"expected a JSON object: {exc}") from exc
    if not isinstance(parsed, dict):
        raise argparse.ArgumentTypeError("expected a JSON object")
    return parsed


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="NSE end-of-day data for the india-* skills (cache, adjust, universe, credits)."
    )
    parser.add_argument(
        "--cache-dir", type=Path, default=None, help=f"default: ${CACHE_ENV} or ./.cache/india-data"
    )
    sub = parser.add_subparsers(dest="command", required=True)

    bars = sub.add_parser("bars", help="Daily bars for one NSE symbol (adjusted by default)")
    bars.add_argument("symbol")
    bars.add_argument("--start", type=_iso_date)
    bars.add_argument("--end", type=_iso_date)
    bars.add_argument(
        "--raw", action="store_true", help="Prices as traded (no bonus/split adjustment)"
    )

    index = sub.add_parser("index", help="Daily bars for an NSE index, e.g. 'NIFTY 50'")
    index.add_argument("name")
    index.add_argument("--start", type=_iso_date)
    index.add_argument("--end", type=_iso_date)

    update = sub.add_parser("update", help="Refresh the bar cache for a universe or symbol list")
    group = update.add_mutually_exclusive_group(required=True)
    group.add_argument("--universe", choices=sorted(UNIVERSE_FILES))
    group.add_argument("--symbols", help="Comma-separated NSE symbols")
    update.add_argument("--start", type=_iso_date, default=date(2024, 1, 1))
    update.add_argument("--limit", type=int, default=None, help="Only the first N symbols")

    universe = sub.add_parser("universe", help="Constituents of a Nifty index")
    universe.add_argument("key", choices=sorted(UNIVERSE_FILES))

    sub.add_parser("session", help="Latest NSE session whose bhavcopy is final")

    ledger = sub.add_parser("ledger", help="Credit ledger for metered sources")
    ledger_sub = ledger.add_subparsers(dest="ledger_command", required=True)
    record = ledger_sub.add_parser("record", help="Log credits spent on one call")
    record.add_argument("--source", required=True, choices=sorted(CREDIT_BUDGETS))
    record.add_argument("--tool", required=True)
    record.add_argument("--credits", required=True, type=float)
    record.add_argument("--note", default="")
    ledger_sub.add_parser("status", help="Credits used and remaining, with warnings")

    metered = sub.add_parser("metered", help="Cache for DalalOS / Drishti responses")
    metered_sub = metered.add_subparsers(dest="metered_command", required=True)
    put = metered_sub.add_parser("put", help="Store a response payload (JSON file)")
    get = metered_sub.add_parser("get", help="Print a cached payload; exit 1 on miss")
    for p in (put, get):
        p.add_argument("--source", required=True, choices=sorted(CREDIT_BUDGETS))
        p.add_argument("--tool", required=True)
        p.add_argument("--args", required=True, type=_json_object, help="Tool arguments as JSON")
    put.add_argument("--payload-file", required=True, type=Path)
    put.add_argument("--ttl-days", required=True, type=float)
    return parser


def _print_json(data: Any) -> None:
    print(json.dumps(data, ensure_ascii=False, indent=2, default=str))


def _run(args: argparse.Namespace, root: Path, cache: BarCache, now_fn: Callable) -> int:
    today = _require_aware(now_fn()).astimezone(IST).date()
    if args.command in ("bars", "index"):
        end = args.end or today
        start = args.start or end - timedelta(days=400)
        if args.command == "bars":
            _print_json(cache.stock_bars(args.symbol, start, end, adjusted=not args.raw))
        else:
            _print_json(cache.index_bars(args.name, start, end))
        return 0
    if args.command == "update":
        if args.universe:
            symbols = [row["symbol"] for row in load_universe(args.universe, root, now_fn=now_fn)]
        else:
            symbols = [s for s in (args.symbols or "").split(",") if s.strip()]
        if args.limit is not None:
            symbols = symbols[: max(0, args.limit)]
        updated, failed = [], {}
        for position, symbol in enumerate(symbols, 1):
            try:
                cache.stock_bars(symbol, args.start, today)
                updated.append(symbol)
            except (IndiaDataError, ValueError) as exc:
                failed[symbol] = str(exc)
            print(f"[{position}/{len(symbols)}] {symbol}", file=sys.stderr)
        _print_json({"updated": len(updated), "failed": failed})
        return 0 if updated or not symbols else 1
    if args.command == "universe":
        _print_json(load_universe(args.key, root, now_fn=now_fn))
        return 0
    if args.command == "session":
        latest = latest_completed_session(now_fn(), sessions_fn=cache._sessions_fn)
        _print_json({"latest_completed_session": latest.isoformat(), "timezone": TIMEZONE_NAME})
        return 0
    if args.command == "ledger":
        ledger = CreditLedger(root / "credit_ledger.jsonl")
        if args.ledger_command == "record":
            ledger.record(args.source, args.tool, args.credits, note=args.note)
        _print_json(ledger.status())
        return 0
    if args.command == "metered":
        store = MeteredCache(root)
        if args.metered_command == "put":
            payload = json.loads(args.payload_file.read_text(encoding="utf-8"))
            path = store.put(args.source, args.tool, args.args, payload, ttl_days=args.ttl_days)
            _print_json({"stored": str(path)})
            return 0
        payload = store.get(args.source, args.tool, args.args)
        if payload is None:
            print("cache miss", file=sys.stderr)
            return 1
        _print_json(payload)
        return 0
    raise ValueError(f"Unknown command {args.command!r}")


def main(
    argv: list | None = None,
    *,
    client: McpHttpClient | None = None,
    sessions_fn: Callable[[date, date], list] | None = None,
    now_fn: Callable[[], datetime] | None = None,
) -> int:
    args = _build_parser().parse_args(argv)
    root = args.cache_dir or default_cache_dir()
    now_fn = now_fn or _utcnow
    cache = BarCache(root, client, sessions_fn=sessions_fn or nse_sessions, now_fn=now_fn)
    try:
        return _run(args, root, cache, now_fn)
    except CalendarDependencyMissingError as exc:
        print(f"Error: missing dependency. {exc}", file=sys.stderr)
        return 2
    except (IndiaDataError, ValueError, OSError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
